            case NetworkState v when topic == TopicType.Network: NetworkChanged?.Invoke(this, v); break;
            case RecordState v when topic == TopicType.Record: RecordChanged?.Invoke(this, v); break;
            case ReplayState v when topic == TopicType.Replay: ReplayChanged?.Invoke(this, v); break;
            case ScenesState v when topic == TopicType.Scenes: ScenesChanged?.Invoke(this, v); break;
            case SourceSettingsState v when topic == TopicType.SourceSettings: SourceSettingsChanged?.Invoke(this, v); break;
            case SourcesState v when topic == TopicType.Sources: SourcesChanged?.Invoke(this, v); break;
            case StatsState v when topic == TopicType.Stats: StatsChanged?.Invoke(this, v); break;
            case StreamState v when topic == TopicType.Stream: StreamChanged?.Invoke(this, v); break;
            case StreamInfoState v when topic == TopicType.StreamInfo: StreamInfoChanged?.Invoke(this, v); break;
            case ThemeState v when topic == TopicType.Theme: ThemeChanged?.Invoke(this, v); break;
            case TransitionsState v when topic == TopicType.Transitions: TransitionsChanged?.Invoke(this, v); break;
            case UpdateState v when topic == TopicType.Update: UpdateChanged?.Invoke(this, v); break;
            case VariablesState v when topic == TopicType.Variables: VariablesChanged?.Invoke(this, v); break;
            case VcamState v when topic == TopicType.Vcam: VcamChanged?.Invoke(this, v); break;
            case VeloqState v when topic == TopicType.Veloq: VeloqChanged?.Invoke(this, v); break;
            case WebState v when topic == TopicType.Web: WebChanged?.Invoke(this, v); break;
        }
    }
